$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'pubspec.yaml'))) { throw 'Execute este script na raiz do projeto Flutter (onde fica o pubspec.yaml).' }
$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backup = Join-Path $root ('backup_evena_' + $stamp)
New-Item -ItemType Directory -Force -Path $backup | Out-Null
Write-Host ('Backup: ' + $backup) -ForegroundColor Yellow

$target = Join-Path $root 'lib\main.dart'
$targetDir = Split-Path $target -Parent
New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
if (Test-Path $target) {
  $backupFile = Join-Path $backup 'lib\main.dart'
  New-Item -ItemType Directory -Force -Path (Split-Path $backupFile -Parent) | Out-Null
  Copy-Item $target $backupFile -Force
}
$b64_lib_main_dart = ''
[IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($b64_lib_main_dart))
Write-Host 'OK  lib/main.dart' -ForegroundColor Green

