Write-Host ''
Write-Host 'Arquivos criados. Agora atualizando o Flutter...' -ForegroundColor Cyan
flutter pub get
if ($LASTEXITCODE -ne 0) { throw 'flutter pub get falhou.' }
dart format lib
if ($LASTEXITCODE -ne 0) { Write-Warning 'dart format retornou erro; confira se o Dart esta no PATH.' }
flutter analyze
if ($LASTEXITCODE -ne 0) { Write-Warning 'flutter analyze encontrou avisos/erros. Leia a saida acima antes de rodar.' }
Write-Host ''
Write-Host 'Pronto. Com o emulador aberto, rode: flutter run' -ForegroundColor Green
